Here is the commit message:
HID: bpf: prevent buffer overflow in hid_hw_request

right now the returned value is considered to be always valid. However,
when playing with HID-BPF, the return value can be arbitrary big,
because it's the return value of dispatch_hid_bpf_raw_requests(), which
calls the struct_ops and we have no guarantees that the value makes
sense.

Fixes: 8bd0488b5ea5 ("HID: bpf: add HID-BPF hooks for hid_hw_raw_requests")
Cc: stable@vger.kernel.org
Acked-by: Jiri Kosina <jkosina@suse.com>
Signed-off-by: Benjamin Tissoires <bentiss@kernel.org>

Here is the root cause:
In `hid_bpf_hw_request()`, the return value from `dispatch_hid_bpf_raw_requests()` (which calls BPF struct_ops) is used directly as the copy length in `memcpy` without validation. A BPF program can return an arbitrarily large value, causing a buffer overflow when copying data into `buf` with size `size`.

Here is the patch:
  */
 __bpf_kfunc int
 hid_bpf_hw_request(struct hid_bpf_ctx *ctx, __u8 *buf, size_t buf__sz,
 		   enum hid_report_type rtype, enum hid_class_request reqtype)
 {
 	struct hid_bpf_ctx_kern *ctx_kern;
 	size_t size = buf__sz;
 	u8 *dma_data;
 	int ret;

 	ctx_kern = container_of(ctx, struct hid_bpf_ctx_kern, ctx);

 	if (ctx_kern->from_bpf)
 		return -EDEADLOCK;

 	/* check arguments */
 	ret = __hid_bpf_hw_check_params(ctx, buf, &size, rtype);
 	if (ret)
 		return ret;

 	switch (reqtype) {
 	case HID_REQ_GET_REPORT:
 	case HID_REQ_GET_IDLE:
 	case HID_REQ_GET_PROTOCOL:
 	case HID_REQ_SET_REPORT:
 	case HID_REQ_SET_IDLE:
 	case HID_REQ_SET_PROTOCOL:
 		break;
 	default:
 		return -EINVAL;
 	}

 	dma_data = kmemdup(buf, size, GFP_KERNEL);
 	if (!dma_data)
 		return -ENOMEM;

 	ret = hid_ops->hid_hw_raw_request(ctx->hid,
 					      dma_data[0],
 					      dma_data,
 					      size,
 					      rtype,
 					      reqtype,
 					      (u64)(long)ctx,
 					      true); /* prevent infinite recursions */

+	if (ret > size)
+		ret = size;
 	if (ret > 0)
 		memcpy(buf, dma_data, ret);

 	kfree(dma_data);
 	return ret;
 }



